import Anthropic from "@anthropic-ai/sdk";
import { readFileSync } from "node:fs";

const client = new Anthropic();
const handbook = readFileSync("handbook.md", "utf8"); // ~12 тысяч токенов

async function ask(question: string) {
  const msg = await client.messages.create({
    model: "claude-sonnet-5",
    max_tokens: 500,
    system: [
      { type: "text", text: "Answer only from the handbook. Quote the section." },
      // всё до этого блока включительно станет кэшируемым префиксом
      { type: "text", text: handbook, cache_control: { type: "ephemeral" } },
    ],
    messages: [{ role: "user", content: question }],
  });
  const u = msg.usage;
  console.log(u.cache_creation_input_tokens, u.cache_read_input_tokens, u.input_tokens);
  return msg;
}

async function main() {
  await ask("Can I get a refund on an annual plan?"); // 1-й вызов: пишет кэш
  await ask("Is 2FA required for admins?");          // в пределах 5 минут: читает кэш
}
main();

// Псевдокод поиска с фильтром по правам (форма фильтра как в Pinecone)
const hits = await index.query({
  vector: await embed(question),
  topK: 8,
  filter: { allowed_groups: { $in: user.groups } }, // фильтр ДО ранжирования
});

